const s=input.state,e=input.event;
const name=t=>t===2?'Мел':'Янтарь';
if(e.type==='action'){
  const a=e.actionId;
  if(a==='teamChoice'){
    s.team=Number(e.value)===2?2:1;
    s.denied='';
  } else if(a==='quiz'||a==='puzzle'||a==='hint'){
    const d=a==='quiz'?3:a==='puzzle'?2:-5;
    const label=a==='quiz'?'Викторина':a==='puzzle'?'Пазл':'Подсказка';
    const bal=s.team===2?s.mel:s.yantar;
    if(d<0&&bal<5){
      s.denied='У команды «'+name(s.team)+'» ' + bal + ' очк. Подсказка стоит 5. В долг нельзя — баланс не изменён.';
    } else {
      const nb=bal+d;
      if(s.team===2){s.mel=nb;}else{s.yantar=nb;}
      s.seq=s.seq+1;
      let at='';
      try{const t=new Date();at=('0'+t.getHours()).slice(-2)+':'+('0'+t.getMinutes()).slice(-2)+':'+('0'+t.getSeconds()).slice(-2);}catch(_){at='';}
      s.history=s.history.concat([{id:'h'+s.seq,team:name(s.team),action:label,change:(d>0?'+':'−')+Math.abs(d),delta:d,at:at,undone:false}]);
      if(s.history.length>100){s.history=s.history.slice(s.history.length-100);}
      s.denied='';
    }
  } else if(a==='undo'){
    let i=-1;
    for(let k=s.history.length-1;k>=0;k--){
      if(s.history[k].undone===false){i=k;break;}
    }
    if(i<0){
      s.denied='История пуста — отменять нечего.';
    } else {
      const r=s.history[i];
      const base=r.team==='Мел'?s.mel:s.yantar;
      const nb=Math.max(0,base-r.delta);
      if(r.team==='Мел'){s.mel=nb;}else{s.yantar=nb;}
      const h=s.history.slice();
      h[i]={id:r.id,team:r.team,action:r.action+' (отменено)',change:'0',delta:r.delta,at:r.at,undone:true};
      s.history=h;
      s.denied='Отменено: '+r.action+' у команды «'+r.team+'».';
    }
  }
}
return {state:s};
